/**
 * @param {number[]} nums
 * @param {number} l
 * @param {number} r
 * @return {number}
 */
var minimumSumSubarray = function(nums, l, r) {
    const n = nums.length;
    let min = Infinity;

    for (let i = l; i <= r; i++) {
        for (let j = 0; j < n; j++) {
            let sum = 0;

            for (let k = j; k < n; k++) {
                sum += nums[k];

                if (k - j + 1 < i) continue;

                if (k - j + 1 > i) {
                    sum -= nums[k - i];
                }

                if (sum > 0) {
                    min = Math.min(min, sum);
                }
            }
        }
    }

    return min < Infinity ? min : -1;
};

