var minimumSumSubarray = function(nums, l, r) {
    const n = nums.length;
    let res = Infinity;
    const iLen = n - l + 1;

    for (let i = 0; i < iLen; i++) {
        const jLen = Math.min(i + r, n);
        let sum = 0;

